# Generated by manage.py generate_test_cases.
from django.urls import reverse

from bloomerp.models.communication.instant_messaging import (
    IMConversation,
    IMConversationParticipant,
    IMMessage,
)
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestConversationsComponent(BloomerpComponentTestCase):
    """Exercise saved conversation discovery without exposing nonmember history."""

    view_name = "components_im_conversations"

    def prepare_conversations(self, scenario: RequestScenario) -> None:
        """Create one visible conversation and one private conversation."""
        connection = None
        chat = IMConversation.objects.create(
            connection=connection, name="Visible discussion"
        )
        member = IMConversationParticipant.objects.create(
            conversation=chat, user=self.normal_user
        )
        IMMessage.objects.create(
            conversation=chat, sender=member, sequence=1, body="Find this message"
        )
        IMConversation.objects.create(connection=connection, name="Hidden discussion")
        self.detail_url = reverse(
            "components_conversation", kwargs={"conversation_id": chat.pk}
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check membership scoping, message search, empty results and login."""
        return [
            RequestScenario(
                name="Member conversations link to reusable fragment",
                user=self.normal_user,
                prepare=self.prepare_conversations,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Visible discussion"),
                        self.does_not_contain_text("Hidden discussion"),
                        self.contains_text('hx-target="#im-conversation-host"'),
                    ]
                ),
            ),
            RequestScenario(
                name="Message search finds conversation",
                user=self.normal_user,
                prepare=self.prepare_conversations,
                query_params={"q": "Find this"},
                expected=ExpectedResult(
                    response_validators=[self.contains_text("Visible discussion")]
                ),
            ),
            RequestScenario(
                name="Search cannot find private conversation",
                user=self.normal_user,
                prepare=self.prepare_conversations,
                query_params={"q": "Hidden"},
                expected=ExpectedResult(
                    response_validators=[
                        self.does_not_contain_text("Hidden discussion"),
                        self.contains_text("No conversations found."),
                    ]
                ),
            ),
            RequestScenario(
                name="Anonymous login required",
                expected=ExpectedResult(status_code=302),
            ),
        ]
